//! Test helper: a fresh in-memory database and a way to send requests through
//! the router without a socket.
//!
//!     var env = try TestEnv.init();
//!     defer env.deinit();
//!     try env.expect(.POST, "/notes", "{\"title\":\"a\"}", .created, null);

const std = @import("std");
const testing = std.testing;
const api = @import("api.zig");
const router = @import("router.zig");
const Pool = @import("db/Pool.zig");

const TestEnv = @This();

pool: Pool,
arena: std.heap.ArenaAllocator,

pub fn init() !TestEnv {
    // One connection: every `:memory:` connection is a separate database.
    return .{
        .pool = try Pool.init(testing.allocator, ":memory:", .{ .size = 1 }),
        .arena = .init(testing.allocator),
    };
}

pub fn deinit(env: *TestEnv) void {
    env.pool.deinit();
    env.arena.deinit();
}

/// Sends a request through the router. The response lives until `deinit`.
pub fn request(env: *TestEnv, method: api.Method, target: []const u8, body: []const u8) !api.Response {
    const ctx: api.Context = .{ .io = testing.io, .arena = env.arena.allocator(), .pool = &env.pool };
    return router.dispatch(&ctx, .init(method, target, body));
}

/// Sends a request and checks the status and, unless `expected_json` is null,
/// that the body is JSON equal to `expected_json` (ignoring formatting).
pub fn expect(
    env: *TestEnv,
    method: api.Method,
    target: []const u8,
    body: []const u8,
    status: api.Status,
    expected_json: ?[]const u8,
) !void {
    const res = try env.request(method, target, body);
    testing.expectEqual(status, res.status) catch |err| {
        std.debug.print("{t} {s}: unexpected status, body: {s}\n", .{ method, target, res.body });
        return err;
    };
    const want = expected_json orelse return;
    try testing.expectEqual(.json, res.content_type);
    try expectJsonEqual(env.arena.allocator(), want, res.body);
}

/// Compares two JSON documents by re-serializing both in a canonical form.
pub fn expectJsonEqual(arena: std.mem.Allocator, expected: []const u8, actual: []const u8) !void {
    const canonical_expected = try canonicalJson(arena, expected);
    const canonical_actual = canonicalJson(arena, actual) catch |err| {
        std.debug.print("response is not valid JSON: {s}\n", .{actual});
        return err;
    };
    try testing.expectEqualStrings(canonical_expected, canonical_actual);
}

fn canonicalJson(arena: std.mem.Allocator, text: []const u8) ![]const u8 {
    const value = try std.json.parseFromSliceLeaky(std.json.Value, arena, text, .{});
    return std.json.Stringify.valueAlloc(arena, value, .{});
}

//! Types shared by the router and the endpoint handlers. Handlers see a
//! transport-independent `Request` and return a `Response`; `server.zig`
//! translates both to and from HTTP.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const Pool = @import("db/Pool.zig");
const sqlite = @import("db/sqlite.zig");

pub const Method = std.http.Method;
pub const Status = std.http.Status;

pub const Request = struct {
    method: Method,
    /// The path without the query string, e.g. `/notes/3`.
    path: []const u8,
    /// The raw query string without the leading `?`; empty if there is none.
    query: []const u8 = "",
    /// The request body; empty for methods without one.
    body: []const u8 = "",

    /// Builds a request from an HTTP request target such as `/notes?tag=a`.
    pub fn init(method: Method, target: []const u8, body: []const u8) Request {
        const path, const query = if (std.mem.indexOfScalar(u8, target, '?')) |i|
            .{ target[0..i], target[i + 1 ..] }
        else
            .{ target, "" };
        return .{ .method = method, .path = path, .query = query, .body = body };
    }
};

test "Request.init splits the query string" {
    const with_query: Request = .init(.GET, "/notes?tag=a&q=b", "");
    try std.testing.expectEqualStrings("/notes", with_query.path);
    try std.testing.expectEqualStrings("tag=a&q=b", with_query.query);

    const without: Request = .init(.GET, "/notes", "");
    try std.testing.expectEqualStrings("/notes", without.path);
    try std.testing.expectEqualStrings("", without.query);
}

pub const Response = struct {
    status: Status,
    content_type: ContentType = .json,
    body: []const u8 = "",
    /// Value of the `Allow` header, set on 405 responses.
    allow: ?[]const u8 = null,

    pub const ContentType = enum {
        json,
        text,
        none,

        pub fn header(content_type: ContentType) ?[]const u8 {
            return switch (content_type) {
                .json => "application/json",
                .text => "text/plain; charset=utf-8",
                .none => null,
            };
        }
    };

    /// A JSON response with `value` serialized as the body.
    pub fn json(arena: Allocator, status: Status, value: anytype) Allocator.Error!Response {
        const body = try std.json.Stringify.valueAlloc(arena, value, .{});
        return .{ .status = status, .body = body };
    }

    pub fn text(status: Status, body: []const u8) Response {
        return .{ .status = status, .content_type = .text, .body = body };
    }

    /// A response without a body, e.g. 204.
    pub fn empty(status: Status) Response {
        return .{ .status = status, .content_type = .none };
    }

    /// An error response with the body `{"error": message}`.
    pub fn err(arena: Allocator, status: Status, message: []const u8) Allocator.Error!Response {
        return json(arena, status, .{ .@"error" = message });
    }

    pub fn notFound(arena: Allocator) Allocator.Error!Response {
        return err(arena, .not_found, "not found");
    }

    pub fn badRequest(arena: Allocator, message: []const u8) Allocator.Error!Response {
        return err(arena, .bad_request, message);
    }

    pub fn methodNotAllowed(arena: Allocator, allow: []const u8) Allocator.Error!Response {
        var response = try err(arena, .method_not_allowed, "method not allowed");
        response.allow = allow;
        return response;
    }
};

/// Per-request state handed to every handler.
pub const Context = struct {
    io: Io,
    /// Freed when the response has been sent; use it for all request-scoped
    /// allocations.
    arena: Allocator,
    pool: *Pool,

    /// Exclusive use of a database connection for the rest of the handler:
    ///
    ///     const conn = try ctx.acquireDb();
    ///     defer ctx.releaseDb(conn);
    ///
    /// Acquire at most one connection per request: holding one while waiting
    /// for another can deadlock when the pool is exhausted (tests use a pool
    /// of one).
    pub fn acquireDb(ctx: *const Context) Io.Cancelable!sqlite.Conn {
        return ctx.pool.acquire(ctx.io);
    }

    pub fn releaseDb(ctx: *const Context, conn: sqlite.Conn) void {
        ctx.pool.release(ctx.io, conn);
    }
};

//! A fixed-size pool of SQLite connections to one database file.
//!
//! Connections are opened in multi-thread mode, so each one must be used by a
//! single task at a time; `acquire` hands out exclusive access and blocks while
//! every connection is in use. The database runs in WAL mode so readers do not
//! block the (single) writer.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const sqlite = @import("sqlite.zig");
const schema = @import("schema.zig");

const Pool = @This();

gpa: Allocator,
all: []sqlite.Conn,
/// Stack of connections not currently handed out. Guarded by `mutex`.
idle: []sqlite.Conn,
idle_len: usize,
mutex: Io.Mutex = .init,
available: Io.Condition = .init,

pub const Options = struct {
    size: usize = 8,
    /// How long a connection waits for a lock held by another connection.
    busy_timeout_ms: u31 = 5000,
};

/// Opens `options.size` connections to `path`, creating the database file and
/// applying the schema if needed.
pub fn init(gpa: Allocator, path: [:0]const u8, options: Options) !Pool {
    std.debug.assert(options.size > 0);

    const all = try gpa.alloc(sqlite.Conn, options.size);
    errdefer gpa.free(all);
    const idle = try gpa.alloc(sqlite.Conn, options.size);
    errdefer gpa.free(idle);

    var opened: usize = 0;
    errdefer for (all[0..opened]) |conn| conn.close();

    while (opened < all.len) : (opened += 1) {
        const conn = try sqlite.Conn.open(path, .{});
        errdefer conn.close();
        try conn.busyTimeout(options.busy_timeout_ms);
        if (opened == 0) {
            // Persistent database settings and migrations: once, before any
            // other connection uses the file.
            try conn.execScript("PRAGMA journal_mode = WAL");
            try schema.migrate(conn);
        }
        try conn.execScript("PRAGMA foreign_keys = ON");
        all[opened] = conn;
    }

    @memcpy(idle, all);
    return .{ .gpa = gpa, .all = all, .idle = idle, .idle_len = idle.len };
}

/// Closes every connection. All connections must have been released.
pub fn deinit(pool: *Pool) void {
    std.debug.assert(pool.idle_len == pool.all.len);
    for (pool.all) |conn| conn.close();
    pool.gpa.free(pool.all);
    pool.gpa.free(pool.idle);
    pool.* = undefined;
}

/// Takes exclusive use of a connection, waiting until one is free. Return it
/// with `release`.
pub fn acquire(pool: *Pool, io: Io) Io.Cancelable!sqlite.Conn {
    try pool.mutex.lock(io);
    defer pool.mutex.unlock(io);
    while (pool.idle_len == 0) try pool.available.wait(io, &pool.mutex);
    pool.idle_len -= 1;
    return pool.idle[pool.idle_len];
}

pub fn release(pool: *Pool, io: Io, conn: sqlite.Conn) void {
    // A connection must never be returned in the middle of a transaction.
    conn.rollback();
    pool.mutex.lockUncancelable(io);
    defer pool.mutex.unlock(io);
    std.debug.assert(pool.idle_len < pool.idle.len);
    pool.idle[pool.idle_len] = conn;
    pool.idle_len += 1;
    pool.available.signal(io);
}

test "acquire and release" {
    const io = std.testing.io;
    var pool = try Pool.init(std.testing.allocator, ":memory:", .{ .size = 2 });
    defer pool.deinit();

    const a = try pool.acquire(io);
    const b = try pool.acquire(io);
    try std.testing.expect(a.handle != b.handle);
    try std.testing.expectEqual(0, pool.idle_len);
    pool.release(io, a);
    pool.release(io, b);
    try std.testing.expectEqual(2, pool.idle_len);
}

//! Database schema, versioned with `PRAGMA user_version`.
//!
//! To change the schema, append a migration to `migrations`; never edit one
//! that has shipped. Each migration runs in its own transaction.

const std = @import("std");
const sqlite = @import("sqlite.zig");

const log = std.log.scoped(.schema);

const migrations = [_][:0]const u8{
    // 1: notes and their tags.
    //
    // AUTOINCREMENT guarantees that ids are never reused, even after the note
    // with the highest id is deleted. Tags live in their own table so that
    // filtering by tag and counting tags are index lookups.
    \\CREATE TABLE notes (
    \\    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    \\    title TEXT NOT NULL,
    \\    body  TEXT NOT NULL DEFAULT ''
    \\);
    \\CREATE TABLE note_tags (
    \\    note_id INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
    \\    tag     TEXT    NOT NULL,
    \\    PRIMARY KEY (note_id, tag)
    \\) WITHOUT ROWID;
    \\CREATE INDEX note_tags_by_tag ON note_tags (tag, note_id);
    ,
};

pub const latest_version = migrations.len;

/// Brings the database up to `latest_version`.
pub fn migrate(conn: sqlite.Conn) !void {
    try conn.begin(.immediate);
    errdefer conn.rollback();

    const current = try userVersion(conn);
    if (current > latest_version) {
        log.err("database schema version {d} is newer than this program ({d})", .{ current, latest_version });
        return error.UnsupportedSchemaVersion;
    }
    for (migrations[current..], current + 1..) |sql, version| {
        log.info("applying schema migration {d}", .{version});
        try conn.execScript(sql);
    }
    if (current != latest_version) {
        var buf: [64]u8 = undefined;
        const pragma = std.fmt.bufPrintZ(&buf, "PRAGMA user_version = {d}", .{latest_version}) catch unreachable;
        try conn.execScript(pragma);
    }
    try conn.commit();
}

fn userVersion(conn: sqlite.Conn) !usize {
    var stmt = try conn.prepare("PRAGMA user_version");
    defer stmt.finalize();
    _ = try stmt.step();
    return @intCast(stmt.columnInt(0));
}

test "migrate is idempotent" {
    const conn = try sqlite.Conn.open(":memory:", .{});
    defer conn.close();

    try migrate(conn);
    try migrate(conn);
    try std.testing.expectEqual(latest_version, try userVersion(conn));
}

//! Thin, allocation-free wrapper over the SQLite C API.
//!
//! Only the parts of the API the service needs are exposed. Text and blob
//! values are bound with `SQLITE_STATIC`: bound slices must stay alive until
//! the statement is reset or finalized, which is always the case when a
//! statement is prepared, bound and stepped within one scope.

const std = @import("std");
const c = @import("sqlite_c");

const log = std.log.scoped(.sqlite);

pub const Error = error{
    Busy,
    Locked,
    Constraint,
    ReadOnly,
    DiskFull,
    CantOpen,
    Corrupt,
    IoFailure,
    Misuse,
    OutOfMemory,
    SqliteFailure,
};

fn check(rc: c_int) Error!void {
    if (rc == c.SQLITE_OK) return;
    return errorFromCode(rc);
}

fn errorFromCode(rc: c_int) Error {
    return switch (rc & 0xff) {
        c.SQLITE_BUSY => error.Busy,
        c.SQLITE_LOCKED => error.Locked,
        c.SQLITE_CONSTRAINT => error.Constraint,
        c.SQLITE_READONLY => error.ReadOnly,
        c.SQLITE_FULL => error.DiskFull,
        c.SQLITE_CANTOPEN => error.CantOpen,
        c.SQLITE_CORRUPT, c.SQLITE_NOTADB => error.Corrupt,
        c.SQLITE_IOERR => error.IoFailure,
        c.SQLITE_MISUSE => error.Misuse,
        c.SQLITE_NOMEM => error.OutOfMemory,
        else => error.SqliteFailure,
    };
}

pub const OpenFlags = struct {
    read_only: bool = false,
    create: bool = true,
};

pub const Conn = struct {
    handle: *c.sqlite3,

    /// Opens a connection in multi-thread mode: the connection itself must
    /// not be used by two threads at once (see `Pool`).
    pub fn open(path: [:0]const u8, flags: OpenFlags) Error!Conn {
        var raw: c_int = c.SQLITE_OPEN_NOMUTEX | c.SQLITE_OPEN_EXRESCODE;
        raw |= if (flags.read_only) c.SQLITE_OPEN_READONLY else c.SQLITE_OPEN_READWRITE;
        if (flags.create and !flags.read_only) raw |= c.SQLITE_OPEN_CREATE;

        var handle: ?*c.sqlite3 = null;
        const rc = c.sqlite3_open_v2(path.ptr, &handle, raw, null);
        if (rc != c.SQLITE_OK) {
            if (handle) |h| {
                log.err("cannot open '{s}': {s}", .{ path, std.mem.span(c.sqlite3_errmsg(h)) });
                _ = c.sqlite3_close_v2(h);
            }
            return errorFromCode(rc);
        }
        return .{ .handle = handle.? };
    }

    pub fn close(conn: Conn) void {
        _ = c.sqlite3_close_v2(conn.handle);
    }

    /// The most recent error message of this connection.
    pub fn errmsg(conn: Conn) []const u8 {
        return std.mem.span(c.sqlite3_errmsg(conn.handle));
    }

    pub fn busyTimeout(conn: Conn, ms: u31) Error!void {
        try check(c.sqlite3_busy_timeout(conn.handle, ms));
    }

    /// Runs one or more SQL statements that take no parameters and return no
    /// rows of interest.
    pub fn execScript(conn: Conn, sql: [:0]const u8) Error!void {
        var msg: [*c]u8 = null;
        const rc = c.sqlite3_exec(conn.handle, sql.ptr, null, null, &msg);
        defer if (msg != null) c.sqlite3_free(msg);
        if (rc != c.SQLITE_OK) {
            log.err("exec failed: {s}", .{if (msg != null) std.mem.span(msg) else conn.errmsg()});
            return errorFromCode(rc);
        }
    }

    /// Prepares, binds and runs a statement to completion, ignoring rows.
    pub fn exec(conn: Conn, sql: []const u8, args: anytype) Error!void {
        var stmt = try conn.prepare(sql);
        defer stmt.finalize();
        try stmt.bindAll(args);
        while (try stmt.step()) {}
    }

    pub fn prepare(conn: Conn, sql: []const u8) Error!Stmt {
        var handle: ?*c.sqlite3_stmt = null;
        const rc = c.sqlite3_prepare_v2(conn.handle, sql.ptr, @intCast(sql.len), &handle, null);
        if (rc != c.SQLITE_OK) {
            log.err("prepare failed: {s}: {s}", .{ conn.errmsg(), sql });
            return errorFromCode(rc);
        }
        return .{ .handle = handle.?, .conn = conn };
    }

    pub fn lastInsertRowId(conn: Conn) i64 {
        return c.sqlite3_last_insert_rowid(conn.handle);
    }

    /// Rows modified by the most recent INSERT, UPDATE or DELETE.
    pub fn changes(conn: Conn) i64 {
        return c.sqlite3_changes64(conn.handle);
    }

    pub const TransactionKind = enum { deferred, immediate };

    /// Starts a transaction. Use `.immediate` for transactions that write, so
    /// that lock contention is resolved by the busy timeout instead of failing
    /// with `error.Busy` on the first write.
    pub fn begin(conn: Conn, kind: TransactionKind) Error!void {
        try conn.execScript(switch (kind) {
            .deferred => "BEGIN DEFERRED",
            .immediate => "BEGIN IMMEDIATE",
        });
    }

    pub fn commit(conn: Conn) Error!void {
        try conn.execScript("COMMIT");
    }

    /// Rolls back the open transaction, if any. Safe to call from `errdefer`.
    pub fn rollback(conn: Conn) void {
        if (c.sqlite3_get_autocommit(conn.handle) != 0) return;
        conn.execScript("ROLLBACK") catch {};
    }
};

pub const Stmt = struct {
    handle: *c.sqlite3_stmt,
    conn: Conn,

    pub fn finalize(stmt: Stmt) void {
        _ = c.sqlite3_finalize(stmt.handle);
    }

    /// Makes the statement ready to run again; bindings are kept.
    pub fn reset(stmt: Stmt) void {
        _ = c.sqlite3_reset(stmt.handle);
    }

    pub fn clearBindings(stmt: Stmt) void {
        _ = c.sqlite3_clear_bindings(stmt.handle);
    }

    /// Advances to the next row. Returns `true` if a row is available and
    /// `false` once the statement has finished.
    pub fn step(stmt: Stmt) Error!bool {
        const rc = c.sqlite3_step(stmt.handle);
        return switch (rc) {
            c.SQLITE_ROW => true,
            c.SQLITE_DONE => false,
            else => {
                log.debug("step failed: {s}", .{stmt.conn.errmsg()});
                return errorFromCode(rc);
            },
        };
    }

    /// Binds every field of the tuple `args` to parameters 1, 2, … in order.
    pub fn bindAll(stmt: Stmt, args: anytype) Error!void {
        inline for (args, 1..) |arg, index| {
            try stmt.bind(index, arg);
        }
    }

    /// Binds `value` to the 1-based parameter `index`. Supported types are
    /// integers, booleans, strings (bound as TEXT), optionals and `null`.
    pub fn bind(stmt: Stmt, index: c_int, value: anytype) Error!void {
        const T = @TypeOf(value);
        const rc = switch (@typeInfo(T)) {
            .null => c.sqlite3_bind_null(stmt.handle, index),
            .optional => return if (value) |v| stmt.bind(index, v) else stmt.bind(index, null),
            .bool => c.sqlite3_bind_int64(stmt.handle, index, @intFromBool(value)),
            .int, .comptime_int => c.sqlite3_bind_int64(stmt.handle, index, @intCast(value)),
            .float, .comptime_float => c.sqlite3_bind_double(stmt.handle, index, value),
            else => blk: {
                const text: []const u8 = value;
                break :blk c.sqlite3_bind_text64(stmt.handle, index, text.ptr, text.len, c.SQLITE_STATIC, c.SQLITE_UTF8);
            },
        };
        try check(rc);
    }

    pub fn columnIsNull(stmt: Stmt, index: c_int) bool {
        return c.sqlite3_column_type(stmt.handle, index) == c.SQLITE_NULL;
    }

    pub fn columnInt(stmt: Stmt, index: c_int) i64 {
        return c.sqlite3_column_int64(stmt.handle, index);
    }

    /// The TEXT value of a column. Valid until the next `step`, `reset` or
    /// `finalize`; use `columnTextDupe` to keep it.
    pub fn columnText(stmt: Stmt, index: c_int) []const u8 {
        const ptr = c.sqlite3_column_text(stmt.handle, index);
        const len: usize = @intCast(c.sqlite3_column_bytes(stmt.handle, index));
        if (ptr == null) return "";
        return ptr[0..len];
    }

    pub fn columnTextDupe(stmt: Stmt, gpa: std.mem.Allocator, index: c_int) error{OutOfMemory}![]u8 {
        return gpa.dupe(u8, stmt.columnText(index));
    }
};

test "open, write and read back" {
