//! Data access for single notes: creating, loading, and the tag helpers that
//! other queries build on.
//!
//! Functions take a connection from `db.Pool`; returned strings are copied
//! into the caller's allocator (usually the request arena).

const std = @import("std");
const Allocator = std.mem.Allocator;
const sqlite = @import("../db/sqlite.zig");
const note = @import("../note.zig");
const Note = note.Note;

/// Inserts a note with its tags in one transaction and returns it.
pub fn create(conn: sqlite.Conn, input: note.Input) !Note {
    try conn.begin(.immediate);
    errdefer conn.rollback();

    try conn.exec("INSERT INTO notes (title, body) VALUES (?, ?)", .{ input.title, input.body });
    const id = conn.lastInsertRowId();
    try insertTags(conn, id, input.tags);
    try conn.commit();

    return .{ .id = id, .title = input.title, .body = input.body, .tags = input.tags };
}

/// Loads the note with the given id, or returns `null` if there is none.
pub fn get(conn: sqlite.Conn, arena: Allocator, id: i64) !?Note {
    // Read the note and its tags from one snapshot.
    try conn.begin(.deferred);
    defer conn.rollback();

    var stmt = try conn.prepare("SELECT title, body FROM notes WHERE id = ?");
    defer stmt.finalize();
    try stmt.bindAll(.{id});
    if (!try stmt.step()) return null;

    return .{
        .id = id,
        .title = try stmt.columnTextDupe(arena, 0),
        .body = try stmt.columnTextDupe(arena, 1),
        .tags = try tagsOf(conn, arena, id),
    };
}

/// The tags of a note, sorted ascending.
pub fn tagsOf(conn: sqlite.Conn, arena: Allocator, id: i64) ![]const []const u8 {
    var stmt = try conn.prepare("SELECT tag FROM note_tags WHERE note_id = ? ORDER BY tag");
    defer stmt.finalize();
    try stmt.bindAll(.{id});

    var tags: std.ArrayList([]const u8) = .empty;
    while (try stmt.step()) try tags.append(arena, try stmt.columnTextDupe(arena, 0));
    return tags.toOwnedSlice(arena);
}

/// Adds tags to a note. `tags` must already be validated and free of
/// duplicates (see `note.parseInput`). Call inside a write transaction.
pub fn insertTags(conn: sqlite.Conn, id: i64, tags: []const []const u8) !void {
    if (tags.len == 0) return;
    var stmt = try conn.prepare("INSERT INTO note_tags (note_id, tag) VALUES (?, ?)");
    defer stmt.finalize();
    for (tags) |tag| {
        try stmt.bindAll(.{ id, tag });
        _ = try stmt.step();
        stmt.reset();
    }
}

const testing = std.testing;
const schema = @import("../db/schema.zig");

pub fn openTestDb() !sqlite.Conn {
    const conn = try sqlite.Conn.open(":memory:", .{});
    errdefer conn.close();
    try schema.migrate(conn);
    return conn;
}

test "create assigns increasing ids and get reads notes back" {
    const conn = try openTestDb();
    defer conn.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    const first = try create(conn, .{ .title = "first" });
    const second = try create(conn, .{ .title = "second", .body = "text", .tags = &.{ "a", "b" } });
    try testing.expectEqual(1, first.id);
    try testing.expectEqual(2, second.id);

    const loaded = (try get(conn, arena.allocator(), 2)).?;
    try testing.expectEqualStrings("second", loaded.title);
    try testing.expectEqualStrings("text", loaded.body);
    try testing.expectEqual(2, loaded.tags.len);
    try testing.expectEqualStrings("a", loaded.tags[0]);
    try testing.expectEqualStrings("b", loaded.tags[1]);

    const empty = (try get(conn, arena.allocator(), 1)).?;
    try testing.expectEqual(0, empty.tags.len);

    try testing.expectEqual(null, try get(conn, arena.allocator(), 3));
}

test "ids are not reused after the newest note is deleted" {
    const conn = try openTestDb();
    defer conn.close();

    _ = try create(conn, .{ .title = "a" });
    const b = try create(conn, .{ .title = "b", .tags = &.{"t"} });
    try conn.exec("DELETE FROM notes WHERE id = ?", .{b.id});
    const c = try create(conn, .{ .title = "c" });
    try testing.expectEqual(3, c.id);

    // Tags of the deleted note went with it.
    var stmt = try conn.prepare("SELECT count(*) FROM note_tags");
    defer stmt.finalize();
    _ = try stmt.step();
    try testing.expectEqual(0, stmt.columnInt(0));
}

//! Aggregate queries over notes and tags for `GET /stats` and `GET /tags`.
//!
//! A tag counts the notes that have it. Tags of deleted notes are removed with
//! the note (`ON DELETE CASCADE`), so they never count.

const std = @import("std");
const Allocator = std.mem.Allocator;
const sqlite = @import("../db/sqlite.zig");

pub const TagCount = struct {
    tag: []const u8,
    count: i64,
};

pub const Order = enum {
    /// Tag ascending.
    by_tag,
    /// Count descending, then tag ascending.
    by_count,
};

pub const Summary = struct {
    notes: i64,
    /// Ordered by tag ascending.
    tags: []const TagCount,
};

/// The number of notes and the count of every tag, read from one snapshot so
/// that both agree.
pub fn summary(conn: sqlite.Conn, arena: Allocator) !Summary {
    try conn.begin(.deferred);
    defer conn.rollback();

    return .{
        .notes = try noteCount(conn),
        .tags = try tagCounts(conn, arena, .by_tag),
    };
}

pub fn noteCount(conn: sqlite.Conn) !i64 {
    var stmt = try conn.prepare("SELECT count(*) FROM notes");
    defer stmt.finalize();
    _ = try stmt.step();
    return stmt.columnInt(0);
}

/// Every tag in use with the number of notes that have it. Strings are copied
/// into `arena`.
pub fn tagCounts(conn: sqlite.Conn, arena: Allocator, order: Order) ![]const TagCount {
    // `note_tags` has one row per (note, tag), so `count(*)` counts notes; the
    // `(tag, note_id)` index serves the grouping.
    const sql = switch (order) {
        .by_tag => "SELECT tag, count(*) FROM note_tags GROUP BY tag ORDER BY tag",
        .by_count => "SELECT tag, count(*) AS n FROM note_tags GROUP BY tag ORDER BY n DESC, tag",
    };
    var stmt = try conn.prepare(sql);
    defer stmt.finalize();

    var counts: std.ArrayList(TagCount) = .empty;
    while (try stmt.step()) {
        try counts.append(arena, .{
            .tag = try stmt.columnTextDupe(arena, 0),
            .count = stmt.columnInt(1),
        });
    }
    return counts.toOwnedSlice(arena);
}

const testing = std.testing;
const notes = @import("notes.zig");

fn expectCounts(expected: []const TagCount, actual: []const TagCount) !void {
    try testing.expectEqual(expected.len, actual.len);
    for (expected, actual) |want, got| {
        try testing.expectEqualStrings(want.tag, got.tag);
        try testing.expectEqual(want.count, got.count);
    }
}

test "empty database" {
    const conn = try notes.openTestDb();
    defer conn.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    const s = try summary(conn, arena.allocator());
    try testing.expectEqual(0, s.notes);
    try testing.expectEqual(0, s.tags.len);
    try testing.expectEqual(0, (try tagCounts(conn, arena.allocator(), .by_count)).len);
}

test "tag counts in both orders, ignoring deleted notes" {
    const conn = try notes.openTestDb();
    defer conn.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    _ = try notes.create(conn, .{ .title = "1", .tags = &.{ "b", "c" } });
    _ = try notes.create(conn, .{ .title = "2", .tags = &.{ "a", "c" } });
    _ = try notes.create(conn, .{ .title = "3", .tags = &.{ "b", "c" } });
    const gone = try notes.create(conn, .{ .title = "4", .tags = &.{ "a", "d" } });
    _ = try notes.create(conn, .{ .title = "5" });
    try conn.exec("DELETE FROM notes WHERE id = ?", .{gone.id});

    const s = try summary(conn, arena.allocator());
    try testing.expectEqual(4, s.notes);
    try expectCounts(&.{
        .{ .tag = "a", .count = 1 },
        .{ .tag = "b", .count = 2 },
        .{ .tag = "c", .count = 3 },
    }, s.tags);

    try expectCounts(&.{
        .{ .tag = "c", .count = 3 },
        .{ .tag = "b", .count = 2 },
        .{ .tag = "a", .count = 1 },
    }, try tagCounts(conn, arena.allocator(), .by_count));
}

test "equal counts are ordered by tag" {
    const conn = try notes.openTestDb();
    defer conn.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    _ = try notes.create(conn, .{ .title = "1", .tags = &.{ "a-2", "a1", "z" } });
    _ = try notes.create(conn, .{ .title = "2", .tags = &.{"z"} });

    try expectCounts(&.{
        .{ .tag = "z", .count = 2 },
        .{ .tag = "a-2", .count = 1 },
        .{ .tag = "a1", .count = 1 },
    }, try tagCounts(conn, arena.allocator(), .by_count));
}
